INSERT [SCore].[EntityProperties] ([ID], [RowStatus], [Guid], [Name], [LanguageLabelID], [EntityHoBTID], [EntityDataTypeID], [IsReadOnly], [IsImmutable], [IsUppercase], [IsHidden], [IsCompulsory], [MaxLength], [Precision], [Scale], [DoNotTrackChanges], [EntityPropertyGroupID], [SortOrder], [GroupSortOrder], [IsObjectLabel], [DropDownListDefinitionID], [IsParentRelationship], [IsLongitude], [IsLatitude], [IsIncludedInformation], [FixedDefaultValue], [SqlDefaultValueStatement], [AllowBulkChange], [IsVirtual], [ShowOnMobile], [IsAlwaysVisibleInGroup], [IsAlwaysVisibleInGroup_Mobile]) VALUES (1819, 1, N'e9d4abb8-aacf-4ecf-8eac-1dfa642106f7', N'ProjectID', 2521, 122, 2, 0, 0, 0, 1, 1, 4, 10, 0, 0, -1, 0, 0, 0, 70, 0, 0, 0, 0, N'', N'SELECT	p.Guid
FROM	SSop.Projects AS p 
WHERE	(p.Guid = ''[[ParentGuid]]'')
UNION ALL 
SELECT	p.Guid
FROM	SSop.Projects AS p 
JOIN	SJob.Jobs AS j ON (j.ProjectId = p.ID)
WHERE	(j.Guid = ''[[ParentGuid]]'')
UNION ALL 
SELECT	p.Guid
FROM	SSop.Projects AS p 
JOIN	SSop.Enquiries AS e ON (e.ProjectId = p.ID)
WHERE	(e.Guid = ''[[ParentGuid]]'')
UNION ALL 
SELECT	p.Guid
FROM	SSop.Projects AS p 
JOIN	SSop.Quotes AS q ON (q.ProjectId = p.ID)
WHERE	(q.Guid = ''[[ParentGuid]]'')', 0, 0, 0, 0, 0)
GO
