INSERT [SCore].[EntityQueries] ([ID], [RowStatus], [Guid], [Name], [Statement], [EntityTypeID], [EntityHoBTID], [IsDefaultCreate], [IsDefaultRead], [IsDefaultUpdate], [IsDefaultDelete], [IsScalarExecute], [IsDefaultValidation], [UsesProcessGuid], [IsDefaultDataPills], [IsProgressData], [IsMergeDocumentQuery], [SchemaName], [ObjectName], [IsManualStatement]) VALUES (260, 1, N'df7a9a4e-7572-43e9-bb17-1c73a0be772e', N'Invoice Request Items Read', N'SELECT 
      root_hobt.ID,
      root_hobt.RowStatus,
      root_hobt.RowVersion,
      root_hobt.Guid,
      ir.Guid AS InvoiceRequestId,
      m.Guid AS MilestoneId,
      a.Guid AS ActivityId,
      root_hobt.Net
  FROM 
      SFin.InvoiceRequestItems root_hobt
  JOIN
     SFin.InvoiceRequests ir ON (ir.Id =  root_hobt.InvoiceRequestId)
  JOIN
    SJob.Milestones m ON (m.ID = root_hobt.MilestoneId)
  JOIN
    SJob.Activities a ON (a.ID = root_hobt.ActivityId)
