INSERT [SUserInterface].[DropDownListDefinitions] ([ID], [RowStatus], [Guid], [Code], [NameColumn], [ValueColumn], [SqlQuery], [DefaultSortColumnName], [IsDefaultColumn], [DetailPageUrl], [IsDetailWindowed], [EntityTypeId], [InformationPageUrl], [GroupColumn], [ColourHexColumn], [ExternalSearchPageUrl]) VALUES (3, 1, N'2f119bd0-cb01-49e0-99f7-dc436cf018c4', N'PropertyGroups', N'Name', N'Guid', N'SELECT  root_hobt.Name, root_hobt.Guid 
FROM    Score.EntityPropertyGroups root_hobt 
WHERE   ((EXISTS
            (
                SELECT  1
                FROM    SCore.EntityProperties ep 
                JOIN    SCore.EntityHoBTs h on (ep.EntityHoBTID = h.ID)
                WHERE   (ep.Guid = ''[[RecordGuid]]'')
                    AND (h.EntityTypeID = root_hobt.EntityTypeID)
            )
        ) OR (ID = -1))', N'Name', N'0', N'', 0, 14, N'', N'', N'#000000', N'')
GO
