INSERT [SUserInterface].[DropDownListDefinitions] ([ID], [RowStatus], [Guid], [Code], [NameColumn], [ValueColumn], [SqlQuery], [DefaultSortColumnName], [IsDefaultColumn], [DetailPageUrl], [IsDetailWindowed], [EntityTypeId], [InformationPageUrl], [GroupColumn], [ColourHexColumn], [ExternalSearchPageUrl]) VALUES (8, 1, N'4746ef94-0489-499d-b2c6-a069ab705cba', N'EntityQueries', N'Name', N'Guid', N'SELECT Guid, Name FROM SCore.EntityQueries root_hobt', N'Name', N'0', N'', 0, 7, N'', N'', N'#000000', N'')
GO
INSERT [SUserInterface].[DropDownListDefinitions] ([ID], [RowStatus], [Guid], [Code], [NameColumn], [ValueColumn], [SqlQuery], [DefaultSortColumnName], [IsDefaultColumn], [DetailPageUrl], [IsDetailWindowed], [EntityTypeId], [InformationPageUrl], [GroupColumn], [ColourHexColumn], [ExternalSearchPageUrl]) VALUES (9, 1, N'3f897dcf-0999-46bb-88ff-41c428162595', N'EntityProperties', N'Name', N'Guid', N'SELECT	root_hobt.Guid,
		N''['' + h.SchemaName + ''].['' + h.ObjectName + ''].['' + root_hobt.Name + '']'' AS Name
FROM	SCore.EntityProperties AS root_hobt
JOIN	SCore.EntityHobts h ON (h.ID = root_hobt.EntityHoBTID)
WHERE	(root_hobt.Id = root_hobt.ID)
	OR	(root_hobt.Guid = ''[[CurrentSelectedValueGuid]]'')', N'Name', N'0', N'', 0, 6, N'', N'', N'#000000', N'')
GO
INSERT [SUserInterface].[DropDownListDefinitions] ([ID], [RowStatus], [Guid], [Code], [NameColumn], [ValueColumn], [SqlQuery], [DefaultSortColumnName], [IsDefaultColumn], [DetailPageUrl], [IsDetailWindowed], [EntityTypeId], [InformationPageUrl], [GroupColumn], [ColourHexColumn], [ExternalSearchPageUrl]) VALUES (10, 1, N'7a18b223-1408-4691-8e84-5a3ba2cce266', N'MappedEntityProp', N'Name', N'Guid', N'SELECT
        root_hobt.Guid,
        root_hobt.Name
FROM
        SCore.EntityProperties root_hobt
    JOIN
        SCore.EntityHoBTs      h
            ON (root_hobt.EntityHoBTID = h.ID)
    JOIN
        SCore.EntityQueries    eq
            ON (h.EntityTypeID = eq.EntityTypeID)
WHERE
        (
            (eq.Guid = ''[[ParentGuid]]'')
            AND (''[[ParentGuid]]'' != ''00000000-0000-0000-0000-000000000000'')
        )
        OR
            (
                (''[[ParentGuid]]'' = ''00000000-0000-0000-0000-000000000000'')
                AND ((EXISTS
    (
        SELECT
            1
        FROM
            SCore.EntityQueryParameters eqp
        WHERE
            (eqp.Guid = ''[[RecordGuid]]'')
            AND (eq.ID = eqp.EntityQueryID)
    )
                     )
                    )
            )', N'root_hobt.Name', N'0', N'', 0, 6, N'', N'', N'#000000', N'')
GO
