        root_hobt.RowStatus,
        root_hobt.Guid,
        root_hobt.Name,
        root_hobt.ColumnOrder,
        olfu.Label AS Title,
        root_hobt.IsPrimaryKey,
        root_hobt.IsHidden,
        root_hobt.IsFiltered,
        root_hobt.IsCombo,
        root_hobt.IsLongitude,
        root_hobt.IsLatitude,
        root_hobt.DisplayFormat,
        root_hobt.Width,
        root_hobt.LanguageLabelId
FROM    SUserInterface.GridViewColumnDefinitions root_hobt
OUTER APPLY SCore.ObjectLabelForUser(root_hobt.LanguageLabelId, [[UserId]]) olfu
WHERE   (EXISTS 
          (
            SELECT  1
            FROM    SUserInterface.GridViewDefinitions gvd
            WHERE   (gvd.Guid = ''[[ParentGuid]]'')
                AND (gvd.Id = root_hobt.GridViewDefinitionId)
          )
