FROM [SCore].[WorkflowStatus] root_hobt
WHERE 
	(root_hobt.RowStatus NOT IN (0,254)) AND
	( NOT EXISTS --Exclude system generated statuses.
			(
				SELECT 1 
				FROM [SCore].[WorkflowStatus]
				WHERE 
					ShowInEnquiries = 0 AND
					ShowInQuotes = 0 AND
					ShowInJobs = 0 AND
					root_hobt.ID = ID
			)
	)
', N'ID', N'', 0, N'', N'', 0, 1, 187, -1, 0, 0, 0, 0, 0, 0, 0, CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', 0, 1, 0, 0, 0, 3298, 22, 1, 0, 0, N'', N'', N'', N'', N'', 0, N'', N'', N'', N'', N'')
