INSERT [SUserInterface].[GridViewDefinitions] ([ID], [RowStatus], [Guid], [Code], [GridDefinitionId], [DetailPageUri], [SqlQuery], [DefaultSortColumnName], [SecurableCode], [DisplayOrder], [DisplayGroupName], [MetricSqlQuery], [ShowMetric], [IsDetailWindowed], [EntityTypeID], [MetricTypeID], [MetricMin], [MetricMax], [MetricMinorUnit], [MetricMajorUnit], [MetricStartAngle], [MetricEndAngle], [MetricReversed], [MetricRange1Min], [MetricRange1Max], [MetricRange1ColourHex], [MetricRange2Min], [MetricRange2Max], [MetricRange2ColourHex], [IsDefaultSortDescending], [AllowNew], [AllowExcelExport], [AllowPdfExport], [AllowCsvExport], [LanguageLabelId], [DrawerIconId], [GridViewTypeId], [AllowBulkChange], [ShowOnMobile], [TreeListFirstOrderBy], [TreeListSecondOrderBy], [TreeListThirdOrderBy], [TreeListOrderBy], [TreeListGroupBy], [ShowOnDashboard], [FilteredListCreatedOnColumn], [FilteredListRedStatusIndicatorTxt], [FilteredListOrangeStatusIndicatorTxt], [FilteredListGreenStatusIndicatorTxt], [FilteredListGroupBy]) VALUES (211, 1, N'ef91dab1-c4c4-4e58-be0e-b0f6cc3e33fe', N'WORKFLOWTRANS', 110, N'DynamicEdit', N'SELECT 
	root_hobt.ID,
	root_hobt.RowStatus,
	root_hobt.RowVersion,
	root_hobt.Guid,
	root_hobt.WorkflowID,
	WftF.Name AS FromStatusID,
	WftT.Name AS ToStatusID,
	root_hobt.IsFinal,
	root_hobt.Enabled,
	root_hobt.SortOrder,
	root_hobt.Description
FROM 
	SCore.WorkflowTransition root_hobt
JOIN 
	SCore.Workflow AS Wf ON (root_hobt.WorkflowID = Wf.ID)
JOIN
	SCore.WorkflowStatus AS WfTF ON (WftF.ID = root_hobt.FromStatusID)
JOIN
	SCore.WorkflowStatus AS WfTT ON (WftT.ID = root_hobt.ToStatusID)
WHERE
       Wf.Guid =[[ParentGuid]]', N'SortOrder', N'', 0, N'', N'', 0, 1, 194, -1, 0, 0, 0, 0, 0, 0, 0, CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', 0, 1, 0, 0, 0, 3299, -1, 1, 0, 0, N'', N'', N'', N'', N'', 0, N'', N'', N'', N'', N'')
GO
INSERT [SUserInterface].[GridViewDefinitions] ([ID], [RowStatus], [Guid], [Code], [GridDefinitionId], [DetailPageUri], [SqlQuery], [DefaultSortColumnName], [SecurableCode], [DisplayOrder], [DisplayGroupName], [MetricSqlQuery], [ShowMetric], [IsDetailWindowed], [EntityTypeID], [MetricTypeID], [MetricMin], [MetricMax], [MetricMinorUnit], [MetricMajorUnit], [MetricStartAngle], [MetricEndAngle], [MetricReversed], [MetricRange1Min], [MetricRange1Max], [MetricRange1ColourHex], [MetricRange2Min], [MetricRange2Max], [MetricRange2ColourHex], [IsDefaultSortDescending], [AllowNew], [AllowExcelExport], [AllowPdfExport], [AllowCsvExport], [LanguageLabelId], [DrawerIconId], [GridViewTypeId], [AllowBulkChange], [ShowOnMobile], [TreeListFirstOrderBy], [TreeListSecondOrderBy], [TreeListThirdOrderBy], [TreeListOrderBy], [TreeListGroupBy], [ShowOnDashboard], [FilteredListCreatedOnColumn], [FilteredListRedStatusIndicatorTxt], [FilteredListOrangeStatusIndicatorTxt], [FilteredListGreenStatusIndicatorTxt], [FilteredListGroupBy]) VALUES (212, 1, N'f28988dd-755a-473f-a12a-6d9931b1b7d8', N'RECORDSTATUS', 111, N'DataObjectTransitionDetail', N'SELECT 
	root_hobt.ID,
	root_hobt.Guid,
	root_hobt.RowStatus,
	root_hobt.RowVersion,
	NewStatus.Name AS StatusID,
	PreviousStatus.Name AS OldStatusID,
	root_hobt.Comment,
	root_hobt.DateTimeUTC,
	CreatedBy.FullName AS CreatedByUserId,
	Surveyor.FullName AS SurveyorUserId,
	root_hobt.DataObjectGuid
FROM [SCore].[DataObjectTransition] AS root_hobt
JOIN SCore.Identities AS CreatedBy ON (CreatedBy.ID = root_hobt.CreatedByUserId)
JOIN SCore.Identities AS Surveyor ON (Surveyor.ID = root_hobt.SurveyorUserId)
LEFT JOIN SCore.WorkflowStatus AS PreviousStatus ON (PreviousStatus.ID = root_hobt.OldStatusID)
LEFT JOIN SCore.WorkflowStatus AS NewStatus ON (NewStatus.ID = root_hobt.StatusID)
WHERE root_hobt.DataObjectGuid = ''[[ParentGuid]]''', N'ID', N'', 0, N'', N'', 0, 1, 190, -1, 0, 0, 0, 0, 0, 0, 0, CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', CAST(0 AS Decimal(18, 0)), CAST(0 AS Decimal(18, 0)), N'', 0, 1, 0, 0, 0, 3307, -1, 1, 0, 0, N'', N'', N'', N'', N'', 0, N'', N'', N'', N'', N'')
GO
